alse},{"key":"public.reserve_gmail_api(uuid, text, integer)","name":"reserve_gmail_api","types":["pg_catalog.uuid","pg_catalog.text","pg_catalog.int4"],"acl":false},{"key":"public.save_campaign_template(jsonb, uuid)","name":"save_campaign_template","types":["pg_catalog.jsonb","pg_catalog.uuid"],"acl":false},{"key":"public.save_campaign_template_v37(jsonb, uuid)","name":"save_campaign_template_v37","types":["pg_catalog.jsonb","pg_catalog.uuid"],"acl":true},{"key":"public.save_company_application(uuid, text, integer, uuid)","name":"save_company_application","types":["pg_catalog.uuid","pg_catalog.text","pg_catalog.int4","pg_catalog.uuid"],"acl":false},{"key":"public.save_lender_guidelines(uuid, jsonb, integer, uuid)","name":"save_lender_guidelines","types":["pg_catalog.uuid","pg_catalog.jsonb","pg_catalog.int4","pg_catalog.uuid"],"acl":true},{"key":"public.save_operational_settings(jsonb, uuid)","name":"save_operational_settings","types":["pg_catalog.jsonb","pg_catalog.uuid"],"acl":true},{"key":"public.save_underwriting_settings(jsonb, uuid)","name":"save_underwriting_settings","types":["pg_catalog.jsonb","pg_catalog.uuid"],"acl":true},{"key":"public.snapshot_underwriting_lender_guidelines()","name":"snapshot_underwriting_lender_guidelines","types":[],"acl":false},{"key":"public.snapshot_underwriting_rules()","name":"snapshot_underwriting_rules","types":[],"acl":false},{"key":"public.start_scheduled_campaigns()","name":"start_scheduled_campaigns","types":[],"acl":false},{"key":"public.start_underwriting_api(uuid, uuid, uuid)","name":"start_underwriting_api","types":["pg_catalog.uuid","pg_catalog.uuid","pg_catalog.uuid"],"acl":false},{"key":"public.stop_contact_sequence(uuid, text)","name":"stop_contact_sequence","types":["pg_catalog.uuid","pg_catalog.text"],"acl":false},{"key":"public.suppress_contact(uuid, text)","name":"suppress_contact","types":["pg_catalog.uuid","pg_catalog.text"],"acl":false},{"key":"public.sync_underwriting_progress()","name":"sync_underwriting_p